[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. Always free for patients.">
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy: #1B1464;
      --navy-light: #2a1f8e;
      --yellow: #FFD930;
      --yellow-hover: #f0cc1e;
      --white: #FFFFFF;
      --gray-50: #F8F9FB;
      --gray-100: #F0F2F5;
      --gray-200: #E2E5EA;
      --gray-300: #C5CAD3;
      --gray-400: #8B93A0;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --teal: #0D9488;
      --teal-light: #14B8A6;
      --shadow-sm: 0 1px 3px rgba(27,20,100,0.06);
      --shadow-md: 0 4px 16px rgba(27,20,100,0.08);
      --shadow-lg: 0 8px 32px rgba(27,20,100,0.12);
      --shadow-xl: 0 16px 48px rgba(27,20,100,0.16);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition: 0.2s ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--gray-800);
      line-height: 1.6;
      background: var(--white);
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-100);
      transition: box-shadow var(--transition);
    }

    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      text-decoration: none;
      font-size: 24px;
      font-weight: 800;
      color: var(--navy);
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--navy);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--yellow);
      font-size: 20px;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav-link {
      text-decoration: none;
      color: var(--gray-600);
      font-weight: 500;
      font-size: 15px;
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }

    .nav-link:hover {
      color: var(--navy);
      background: var(--gray-50);
    }

    .nav-btn {
      background: var(--navy);
      color: var(--white);
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      text-decoration: none;
      font-weight: 600;
      font-size: 15px;
      transition: all var(--transition);
      margin-left: 8px;
    }

    .nav-btn:hover {
      background: var(--navy-light);
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }

    .hamburger {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      color: var(--navy);
      font-size: 24px;
      border-radius: var(--radius-sm);
      transition: background var(--transition);
    }

    .hamburger:hover { background: var(--gray-50); }

    .mobile-menu {
      position: fixed;
      top: 0;
      right: -100%;
      width: min(320px, 85vw);
      height: 100vh;
      background: var(--white);
      z-index: 2000;
      padding: 24px;
      transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: var(--shadow-xl);
      display: flex;
      flex-direction: column;
    }

    .mobile-menu.open { right: 0; }

    .mobile-overlay {
      position: fixed;
      inset: 0;
      background: rgba(27,20,100,0.3);
      z-index: 1999;
      opacity: 0;
      visibility: hidden;
      transition: all 0.3s ease;
    }

    .mobile-overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .mobile-menu-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 32px;
    }

    .mobile-close {
      background: none;
      border: none;
      cursor: pointer;
      font-size: 24px;
      color: var(--gray-500);
      padding: 8px;
      border-radius: var(--radius-sm);
    }

    .mobile-close:hover { background: var(--gray-50); }

    .mobile-nav-link {
      display: block;
      text-decoration: none;
      color: var(--gray-700);
      font-weight: 500;
      font-size: 18px;
      padding: 16px 0;
      border-bottom: 1px solid var(--gray-100);
      transition: color var(--transition);
    }

    .mobile-nav-link:hover { color: var(--navy); }

    .mobile-nav-btn {
      display: block;
      background: var(--navy);
      color: var(--white);
      text-align: center;
      padding: 14px 24px;
      border-radius: var(--radius-sm);
      text-decoration: none;
      font-weight: 600;
      font-size: 16px;
      margin-top: 24px;
      transition: background var(--transition);
    }

    .mobile-nav-btn:hover { background: var(--navy-light); }

    /* ===== HERO ===== */
    .hero {
      padding: 140px 24px 80px;
      background: linear-gradient(170deg, var(--navy) 0%, #2a1f8e 50%, #3525a8 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(255,217,48,0.12) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(13,148,136,0.1) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .hero h1 {
      font-size: clamp(32px, 5vw, 52px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.15;
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero p {
      font-size: clamp(16px, 2vw, 19px);
      color: rgba(255,255,255,0.8);
      max-width: 600px;
      margin: 0 auto 40px;
      line-height: 1.7;
    }

    /* ===== SEARCH BAR ===== */
    .search-container {
      max-width: 820px;
      margin: 0 auto;
      position: relative;
      z-index: 10;
    }

    .search-box {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 8px;
      display: flex;
      align-items: center;
      box-shadow: var(--shadow-xl);
      gap: 4px;
    }

    .search-field {
      flex: 1;
      position: relative;
      min-width: 0;
    }

    .search-field input,
    .search-field select {
      width: 100%;
      border: none;
      outline: none;
      padding: 16px 16px 16px 44px;
      font-size: 15px;
      font-family: inherit;
      color: var(--gray-800);
      background: transparent;
      border-radius: var(--radius-md);
      transition: background var(--transition);
    }

    .search-field input:hover,
    .search-field select:hover,
    .search-field input:focus,
    .search-field select:focus {
      background: var(--gray-50);
    }

    .search-field input::placeholder { color: var(--gray-400); }

    .search-field-icon {
      position: absolute;
      left: 16px;
      top: 50%;
      transform: translateY(-50%);
      color: var(--gray-400);
      font-size: 18px;
      pointer-events: none;
      z-index: 1;
    }

    .search-divider {
      width: 1px;
      height: 32px;
      background: var(--gray-200);
      flex-shrink: 0;
    }

    .search-btn {
      background: var(--yellow);
      color: var(--navy);
      border: none;
      padding: 16px 32px;
      font-size: 16px;
      font-weight: 700;
      border-radius: var(--radius-md);
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
      transition: all var(--transition);
      flex-shrink: 0;
      font-family: inherit;
    }

    .search-btn:hover {
      background: var(--yellow-hover);
      transform: translateY(-1px);
      box-shadow: 0 4px 16px rgba(255,217,48,0.4);
    }

    .search-btn i { font-size: 18px; }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-200);
      display: none;
      z-index: 100;
      overflow: hidden;
    }

    .autocomplete-dropdown.show { display: block; }

    .autocomplete-item {
      padding: 12px 16px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 14px;
      color: var(--gray-700);
      transition: background var(--transition);
    }

    .autocomplete-item:hover {
      background: var(--gray-50);
    }

    .autocomplete-item i {
      color: var(--navy);
      font-size: 18px;
      width: 24px;
      text-align: center;
      flex-shrink: 0;
    }

    .autocomplete-item .item-label { font-weight: 500; }

    .autocomplete-item .item-type {
      font-size: 12px;
      color: var(--gray-400);
      margin-left: auto;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      font-weight: 600;
    }

    /* ===== SPECIALTIES ===== */
    .specialties {
      padding: 80px 24px;
      background: var(--white);
    }

    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-label {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      margin-bottom: 8px;
    }

    .section-title {
      font-size: clamp(26px, 3.5vw, 36px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 12px;
      letter-spacing: -0.01em;
    }

    .section-subtitle {
      font-size: 17px;
      color: var(--gray-500);
      margin-bottom: 48px;
      max-width: 520px;
    }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
      gap: 16px;
    }

    .specialty-card {
      background: var(--white);
      border: 2px solid var(--gray-100);
      border-radius: var(--radius-md);
      padding: 28px 20px;
      text-align: center;
      cursor: pointer;
      transition: all 0.25s ease;
      text-decoration: none;
      color: inherit;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
    }

    .specialty-card:hover {
      border-color: var(--navy);
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .specialty-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 26px;
      transition: transform var(--transition);
    }

    .specialty-card:hover .specialty-icon { transform: scale(1.1); }

    .specialty-icon.primary-care { background: #EEF2FF; color: #4F46E5; }
    .specialty-icon.dentist { background: #F0FDFA; color: #0D9488; }
    .specialty-icon.dermatologist { background: #FFF7ED; color: #EA580C; }
    .specialty-icon.psychiatrist { background: #FDF4FF; color: #A855F7; }
    .specialty-icon.eye-doctor { background: #EFF6FF; color: #2563EB; }
    .specialty-icon.orthopedic { background: #FEF2F2; color: #DC2626; }

    .specialty-name {
      font-weight: 600;
      font-size: 15px;
      color: var(--gray-800);
    }

    .specialty-desc {
      font-size: 13px;
      color: var(--gray-400);
      line-height: 1.4;
    }

    /* ===== HOW IT WORKS ===== */
    .how-it-works {
      padding: 80px 24px;
      background: var(--gray-50);
    }

    .steps-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 32px;
      margin-top: 48px;
    }

    .step-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 36px 28px;
      position: relative;
      box-shadow: var(--shadow-sm);
      transition: all 0.25s ease;
    }

    .step-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .step-number {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--navy);
      color: var(--yellow);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 800;
      font-size: 16px;
      margin-bottom: 20px;
    }

    .step-icon {
      font-size: 32px;
      color: var(--navy);
      margin-bottom: 16px;
    }

    .step-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 10px;
    }

    .step-text {
      font-size: 15px;
      color: var(--gray-500);
      line-height: 1.7;
    }

    /* ===== STATS ===== */
    .stats {
      padding: 60px 24px;
      background: var(--navy);
      position: relative;
      overflow: hidden;
    }

    .stats::before {
      content: '';
      position: absolute;
      top: -80px;
      right: -80px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(255,217,48,0.08) 0%, transparent 70%);
      border-radius: 50%;
    }

    .stats-grid {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 32px;
      position: relative;
      z-index: 1;
    }

    .stat-item {
      text-align: center;
      padding: 12px;
    }

    .stat-value {
      font-size: clamp(32px, 4vw, 44px);
      font-weight: 800;
      color: var(--yellow);
      letter-spacing: -0.02em;
      margin-bottom: 4px;
    }

    .stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.7);
      font-weight: 500;
    }

    /* ===== TESTIMONIALS ===== */
    .testimonials {
      padding: 80px 24px;
      background: var(--white);
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 24px;
      margin-top: 48px;
    }

    .testimonial-card {
      background: var(--white);
      border: 2px solid var(--gray-100);
      border-radius: var(--radius-lg);
      padding: 32px;
      transition: all 0.25s ease;
    }

    .testimonial-card:hover {
      border-color: var(--gray-200);
      box-shadow: var(--shadow-md);
    }

    .testimonial-stars {
      color: var(--yellow);
      font-size: 18px;
      margin-bottom: 16px;
      display: flex;
      gap: 2px;
    }

    .testimonial-text {
      font-size: 16px;
      color: var(--gray-600);
      line-height: 1.75;
      margin-bottom: 20px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--navy);
      color: var(--yellow);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 16px;
      flex-shrink: 0;
    }

    .testimonial-name {
      font-weight: 600;
      font-size: 15px;
      color: var(--gray-800);
    }

    .testimonial-location {
      font-size: 13px;
      color: var(--gray-400);
    }

    /* ===== APP PROMO ===== */
    .app-promo {
      padding: 80px 24px;
      background: var(--gray-50);
    }

    .app-promo-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .app-promo-content .section-label { margin-bottom: 8px; }

    .app-features {
      list-style: none;
      margin: 28px 0 36px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .app-features li {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 16px;
      color: var(--gray-600);
    }

    .app-features li i {
      color: var(--teal);
      font-size: 20px;
      flex-shrink: 0;
    }

    .app-buttons {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .app-store-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: var(--navy);
      color: var(--white);
      text-decoration: none;
      padding: 14px 24px;
      border-radius: var(--radius-md);
      font-size: 14px;
      font-weight: 600;
      transition: all var(--transition);
    }

    .app-store-btn:hover {
      background: var(--navy-light);
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }

    .app-store-btn i { font-size: 24px; }

    .app-store-btn .btn-label-small {
      font-size: 11px;
      font-weight: 400;
      opacity: 0.7;
      display: block;
      line-height: 1;
    }

    .app-store-btn .btn-label-main {
      display: block;
      line-height: 1.2;
    }

    .app-phone-mockup {
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .phone-frame {
      width: 280px;
      height: 520px;
      background: var(--navy);
      border-radius: 36px;
      padding: 16px;
      box-shadow: var(--shadow-xl);
      position: relative;
    }

    .phone-screen {
      width: 100%;
      height: 100%;
      background: var(--white);
      border-radius: 24px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 16px;
      padding: 24px;
    }

    .phone-screen .phone-logo {
      font-weight: 800;
      font-size: 22px;
      color: var(--navy);
    }

    .phone-screen .phone-text {
      font-size: 13px;
      color: var(--gray-500);
      text-align: center;
      line-height: 1.5;
    }

    .phone-screen .phone-btn {
      background: var(--yellow);
      color: var(--navy);
      border: none;
      padding: 12px 28px;
      border-radius: var(--radius-sm);
      font-weight: 700;
      font-size: 14px;
      cursor: default;
    }

    .phone-notch {
      position: absolute;
      top: 16px;
      left: 50%;
      transform: translateX(-50%);
      width: 100px;
      height: 24px;
      background: var(--navy);
      border-radius: 0 0 16px 16px;
      z-index: 5;
    }

    /* ===== FOOTER ===== */
    .footer {
      padding: 64px 24px 32px;
      background: var(--navy);
      color: rgba(255,255,255,0.7);
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 40px;
      margin-bottom: 48px;
    }

    .footer-brand {
      grid-column: span 1;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      text-decoration: none;
      font-size: 22px;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-logo .logo-icon {
      background: rgba(255,255,255,0.15);
      color: var(--yellow);
    }

    .footer-brand-text {
      font-size: 14px;
      line-height: 1.7;
      color: rgba(255,255,255,0.5);
    }

    .footer-heading {
      font-size: 14px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--white);
      margin-bottom: 20px;
    }

    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .footer-links a {
      color: rgba(255,255,255,0.6);
      text-decoration: none;
      font-size: 14px;
      transition: color var(--transition);
    }

    .footer-links a:hover { color: var(--yellow); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-copy {
      font-size: 13px;
      color: rgba(255,255,255,0.4);
    }

    .footer-tagline {
      font-size: 13px;
