  <script>
    // Mobile menu
    const hamburgerBtn = document.getElementById('hamburgerBtn');
    const mobileMenu = document.getElementById('mobileMenu');
    const mobileOverlay = document.getElementById('mobileOverlay');
    const mobileCloseBtn = document.getElementById('mobileCloseBtn');

    function openMobileMenu() {
      mobileMenu.classList.add('open');
      mobileOverlay.classList.add('open');
      document.body.style.overflow = 'hidden';
    }

    function closeMobileMenu() {
      mobileMenu.classList.remove('open');
      mobileOverlay.classList.remove('open');
      document.body.style.overflow = '';
    }

    hamburgerBtn.addEventListener('click', openMobileMenu);
    mobileCloseBtn.addEventListener('click', closeMobileMenu);
    mobileOverlay.addEventListener('click', closeMobileMenu);

    // Header scroll effect
    window.addEventListener('scroll', () => {
      document.getElementById('header').classList.toggle('scrolled', window.scrollY > 10);
    });

    // Autocomplete
    const searchInput = document.getElementById('searchInput');
    const dropdown = document.getElementById('autocompleteDropdown');

    const suggestions = [
      { icon: 'ri-stethoscope-line', label: 'Primary Care', type: 'Specialty' },
      { icon: 'ri-tooth-line', label: 'Dentist', type: 'Specialty' },
      { icon: 'ri-sun-line', label: 'Dermatologist', type: 'Specialty' },
      { icon: 'ri-mental-health-line', label: 'Psychiatrist', type: 'Specialty' },
      { icon: 'ri-eye-line', label: 'Eye Doctor', type: 'Specialty' },
      { icon: 'ri-walk-line', label: 'Orthopedic Surgeon', type: 'Specialty' },
      { icon: 'ri-virus-line', label: 'Allergist', type: 'Specialty' },
      { icon: 'ri-heart-pulse-line', label: 'Cardiologist', type: 'Specialty' },
      { icon: 'ri-body-scan-line', label: 'Back pain', type: 'Condition' },
      { icon: 'ri-body-scan-line', label: 'Headache', type: 'Condition' },
      { icon: 'ri-body-scan-line', label: 'Acne', type: 'Condition' },
      { icon: 'ri-body-scan-line', label: 'Anxiety', type: 'Condition' },
      { icon: 'ri-user-heart-line', label: 'Dr. Sarah Chen', type: 'Doctor' },
      { icon: 'ri-user-heart-line', label: 'Dr. Michael Ross', type: 'Doctor' },
      { icon: 'ri-user-heart-line', label: 'Dr. Amira Patel', type: 'Doctor' },
    ];

    searchInput.addEventListener('input', function() {
      const query = this.value.toLowerCase().trim();
      if (query.length === 0) {
        dropdown.classList.remove('show');
        return;
      }

      const filtered = suggestions.filter(s => s.label.toLowerCase().includes(query));

      if (filtered.length === 0) {
        dropdown.classList.remove('show');
        return;
      }

      dropdown.innerHTML = filtered.slice(0, 6).map(s => `
        <div class="autocomplete-item" data-value="${s.label}">
          <i class="${s.icon}"></i>
          <span class="item-label">${s.label}</span>
          <span class="item-type">${s.type}</span>
        </div>
      `).join('');

      dropdown.classList.add('show');

      dropdown.querySelectorAll('.autocomplete-item').forEach(item => {
        item.addEventListener('click', function() {
          searchInput.value = this.dataset.value;
          dropdown.classList.remove('show');
        });
      });
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-field')) {
        dropdown.classList.remove('show');
      }
    });

    // Scroll animations
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.fade-up').forEach(el => observer.observe(el));
  </script>
